pub fn from_name(name: &str, field: &str, patch: &str) -> Result<Self> {
    let k = match name {
        "fixedValue" | "noSlip" => Self::FixedValue,
        "zeroGradient" => Self::ZeroGradient,
        "fixedGradient" | "uniformFixedGradient" => Self::FixedGradient,
        "mixed" | "freestream" | "freestreamVelocity" => Self::Mixed,
        // Its own condition now, and only for a field that says so: a
        // value written by a model and never solved for.
        "calculated" => Self::Calculated,
        "empty" => Self::Empty,
        "symmetry" | "symmetryPlane" | "slip" | "wedge" => Self::Symmetry,
        "cyclic" | "cyclicSlip" | "processor" => Self::Cyclic,
        "inletOutlet" | "freestreamPressure" => Self::InletOutlet,

// patch, so that a missing or unreadable one is reported against the
// condition that wanted it (SPEC-LIT 13.4) rather than defaulted.
let intensity = match kind {
    BcKind::TurbulentIntensityKineticEnergyInlet => Some(spec.required_number(
        "turbulentIntensity",
        patch,
        "turbulentIntensityKineticEnergyInlet",
    )?),
    _ => None,
};
let mixing_length = match kind {
    BcKind::TurbulentMixingLengthDissipationRateInlet
    | BcKind::TurbulentMixingLengthFrequencyInlet => {
        let l = spec.required_number("mixingLength", patch, &spec.type_name)?;
        if !(l > 0.0) {
            return Err(Error::Field {
                field: patch.to_string(),
                msg: format!("{}: mixingLength must be positive, not {l}", spec.type_name),
            });
        }
        Some(l)
    }
    _ => None,
};
let p0 = match kind {
    BcKind::TotalPressure => Some(spec.required_number("p0", patch, "totalPressure")?),
    _ => None,
};
// SPEC-LIT §32.2: the fixed wall heat flux, read once here so a missing
// or unreadable `q` is reported against the condition that wanted it
// (§13.4), same convention as `p0`/`turbulentIntensity` above.
let q_flux = match kind {
    BcKind::FixedFluxTemperature => {
        Some(spec.required_number("q", patch, "fixedFluxTemperature")?)
    }
    _ => None,
};
// SPEC-LIT 39.3: the contact angle, read here on the same convention -
// a missing or unreadable `theta0` is reported against the condition that
// wanted it. `cos_deg` is what maps ninety degrees to EXACTLY zero, which
// is the whole of 39.2's trap: cos(pi/2) is 6.1e-17 and would move every
// recorded VOF measurement for a case that asked for nothing.
let cos_theta0 = match kind {
    BcKind::ContactAngle => Some(crate::contact_angle::cos_deg(
        spec.required_number("theta0", patch, &spec.type_name)?,
    )),
    _ => None,
};

let cmu = aux.inputs.cmu();

for i in 0..n {
    let (fr, rv, rg) = match kind {
        BcKind::FixedValue => (1.0, value[i], 0.0),
        BcKind::FixedGradient => (0.0, 0.0, grad[i]),
        BcKind::Mixed => (vfrac[i], rvalue[i], rgrad[i]),

        // The fraction is rewritten every iteration from the face flux
        // (inflow -> Dirichlet at inletValue, outflow -> zeroGradient).
        // Seeding it as inflow is the safe start: it holds a sensible
        // value on the first assembly, before any flux exists.
        BcKind::InletOutlet => (1.0, inlet[i], 0.0),

        // k = 3/2 (I |U|)^2 - the definition of the turbulence intensity
        // I as the ratio of the r.m.s. velocity fluctuation to the mean,
        // with the three components equal (Launder & Spalding 1974).
        // Flux-switched, exactly as inletOutlet is.
        BcKind::TurbulentIntensityKineticEnergyInlet => {
            let i_t = intensity.unwrap_or(0.0);
            let mag_u = aux
                .u(i, patch, "turbulentIntensityKineticEnergyInlet")?
                .mag();
            let iu = i_t * mag_u;
            (1.0, 1.5 * iu * iu, 0.0)
        }

        // epsilon = C_mu^{3/4} k^{3/2}/L: the equilibrium dissipation of
        // an eddy of size L carrying energy k (Launder & Spalding 1974).
        BcKind::TurbulentMixingLengthDissipationRateInlet => {
            let l = mixing_length.unwrap_or(1.0);
            let kb = aux
                .k(i, patch, "turbulentMixingLengthDissipationRateInlet")?
                .max(0.0);
            (1.0, cmu.powf(0.75) * kb * kb.sqrt() / l, 0.0)
        }

        // omega = epsilon/(C_mu k) applied to the same relation, i.e.
        // k^{1/2}/(C_mu^{1/4} L) (Wilcox).
        BcKind::TurbulentMixingLengthFrequencyInlet => {
            let l = mixing_length.unwrap_or(1.0);
            let kb = aux
                .k(i, patch, "turbulentMixingLengthFrequencyInlet")?
                .max(0.0);
            (1.0, kb.sqrt() / (cmu.powf(0.25) * l), 0.0)
        }

pub enum WallTreatment {
    Standard,
    /// SPEC-LIT §15.1: `nut` gets `y+` from the local velocity (the inverse
    /// Spalding law) rather than from `k`.
    Spalding,
    /// SPEC-LIT §15.3/§29.2: the Cebeci & Bradshaw roughness downshift.
    /// Requires `Ks` - see [`Roughness::resolve`].
    Rough,
    /// SPEC-LIT §15.2: the mesh resolves the viscous sublayer, so NO wall
    /// model constrains any of the four fields - `eps`/`omega` fall back to
    /// plain `zeroGradient` rather than the `*WallFunction` that would
    /// otherwise constrain their wall-adjacent cell (SPEC-LIT §29.1's own
    /// running example of the contradiction this preset mechanism exists to
    /// rule out: `nutLowReWallFunction` together with `epsilonWallFunction`).
    LowRe,
}

impl WallTreatment {
    /// Under the `SPEC-LIT` §13.4 rule; `""` (the case named none) is
    /// `standard`, the OpenFOAM-compatible default.
    pub fn from_name(s: &str) -> Result<Self> {
        match s {
            "standard" | "" => Ok(Self::Standard),
            "spalding" => Ok(Self::Spalding),
            "rough" => Ok(Self::Rough),
            "lowRe" => Ok(Self::LowRe),
            other => unsupported(
                "RAS/wallTreatment",
                other,
                &["standard", "spalding", "rough", "lowRe"],
                "standard",
                Self::Standard,
            ),
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            Self::Standard => "standard",
            Self::Spalding => "spalding",
            Self::Rough => "rough",
            Self::LowRe => "lowRe",
        }
    }

    /// `nut`'s patch type under this row - SPEC-LIT §29.1's table.
    pub fn nut_type(self) -> &'static str {
        match self {
            Self::Standard => "nutkWallFunction",
            Self::Spalding => "nutUWallFunction",
            Self::Rough => "nutkRoughWallFunction",
            Self::LowRe => "nutLowReWallFunction",
        }
    }

    /// `k`'s patch type under this row.
    pub fn k_type(self) -> &'static str {
        match self {
            Self::LowRe => "kLowReWallFunction",
            _ => "kqRWallFunction",
        }
    }

    /// `epsilon`'s patch type under this row.
    ///
    /// `lowRe` pins NO wall FUNCTION (SPEC-LIT §15.2/§29.1), but it does pin
    /// a wall VALUE: SPEC-LIT §33.2's homogeneous Dirichlet,
    /// `epsilon_tilde = 0`, which is what makes the only model this row is
    /// valid under (`LaunderSharmaKE`) correct at the wall rather than
    /// merely unconstrained there. `fixedValue` with no `value` entry is `0`
    /// by construction (`apply_wall_treatment_defaults` writes no `value`,
    /// and an absent one defaults to zero) - there is still no distinct
    /// low-Re-NAMED `epsilon` wall condition in this solver, only a plain
    /// one asked to hold a specific value.
    pub fn epsilon_type(self) -> &'static str {
        match self {
            Self::LowRe => "fixedValue",
            _ => "epsilonWallFunction",
        }
    }

    /// `omega`'s patch type under this row - same reasoning as
    /// [`Self::epsilon_type`].
    pub fn omega_type(self) -> &'static str {
        match self {
            Self::LowRe => "zeroGradient",
            _ => "omegaWallFunction",
        }
    }

    /// SPEC-LIT §29.3: every row applies the Jayatilleke thermal wall
    /// function to `T` on walls when the energy equation is solved, except
    /// `lowRe`, which pins the molecular resistance the resolved mesh already

enum WallRowFamily {
    Full,
    LowRe,
}

fn nut_family(k: BcKind) -> Option<WallRowFamily> {
    if k.is_nut_wall_function() {
        Some(WallRowFamily::Full)
    } else if k.is_nut_low_re() {
        Some(WallRowFamily::LowRe)
    } else {
        None
    }
}

fn k_family(k: BcKind) -> Option<WallRowFamily> {
    match k {
        BcKind::KqRWallFunction => Some(WallRowFamily::Full),
        BcKind::KLowReWallFunction => Some(WallRowFamily::LowRe),
        _ => None,
    }
}

/// `epsilon`'s and `omega`'s own patch types can only ever DECLARE `Full`
/// (`epsilonWallFunction`/`omegaWallFunction` - SPEC-LIT §6.4); there is no
/// distinct low-Re-NAMED condition for either. SPEC-LIT §29.1's `lowRe` row
/// completes `omega` with plain `zeroGradient` and `epsilon` with plain
/// `fixedValue` (0 - SPEC-LIT §33.2's homogeneous Dirichlet), and EITHER
/// reads as "no opinion" here, not a second family: `constrains_wall_cell`
/// is false for both, exactly as it is for `zeroGradient` - a `lowRe` row's
/// `epsilon` never conflicts with another field's `Full` opinion, it simply
/// never has one of its own to conflict with.
fn eps_omega_family(k: BcKind) -> Option<WallRowFamily> {
    if k.constrains_wall_cell() {
        Some(WallRowFamily::Full)
    } else {
        None
    }
}

/// `omega` in the wall-adjacent cell: the root-sum-square blend of
/// `sqrt(k)/(C_mu^{1/4} kappa y)` and Wilcox's `6 nu/(beta_1 y^2)`.
#[inline]
pub fn omega_wall(
    k: Scalar,
    y: Scalar,
    nu: Scalar,
    kappa: Scalar,
    cmu: Scalar,
    beta1: Scalar,
) -> Scalar {
    let w_log = k.max(0.0).sqrt() / (cmu.powf(0.25) * kappa * y);
    let w_vis = 6.0 * nu / (beta1 * y * y);
    (w_log * w_log + w_vis * w_vis).sqrt()
}

/// One source's dictionary entry, as [`read_sources`] understands it.
///
/// *DESIGN.* The format is ours: OpenFOAM expresses this through `fvModels`,
/// `fvOptions` and `topoSet`, none of which this project has, and inventing a
/// partial imitation of them would be worse than a small honest format of our
/// own. `constant/fvSources` (or `system/fvSources`) holds one sub-dictionary
/// per source:
///
/// ```text
/// heater
/// {
///     type        heatRelease;    // the equation it acts on is `field`
///     field       T;
///     Q           50000;          // W
///     rhoCp       1206;           // J/(m3 K) - rho*c_p
///     selection   box;
///     min         (0.4 0.4 0.0);
///     max         (0.6 0.6 0.2);
/// }
///
/// filter
/// {
///     type        porousDrag;     // acts on U
///     d           250;            // nu/K, 1/s
///     f           40;             // C_F,  1/m
///     selection   sphere;
///     centre      (1 1 0.5);
///     radius      0.3;
/// }
/// ```
///
/// `selection` is `box`, `sphere` or `all`. Every other `type` is an ERROR
/// naming what is available, per SPEC-LIT §13.4 - a source the solver cannot
/// apply must not be read and dropped.

fn read_selector(d: &crate::io::dict::FoamDict, name: &str) -> Result<CellSelector> {
    let key = |k: &str| format!("{name}/{k}");
    match d.get_or(&key("selection"), "") {
        "box" => {
            let min = vector(d, &key("min"), name)?;
            let max = vector(d, &key("max"), name)?;
            if !(max.x >= min.x && max.y >= min.y && max.z >= min.z) {
                return Err(Error::Config(format!(
                    "source \"{name}\": the box's max corner is not above its min corner"
                )));
            }
            Ok(CellSelector::Box { min, max })
        }
        "sphere" => {
            let centre = vector(d, &key("centre"), name)
                .or_else(|_| vector(d, &key("center"), name))?;
            let radius = required(d, &key("radius"), name, "the sphere's radius")?;
            if !(radius > 0.0) {
                return Err(Error::Config(format!(
                    "source \"{name}\": the sphere's radius is {radius}"
                )));
            }
            Ok(CellSelector::Sphere { centre, radius })
        }
        "all" => Ok(CellSelector::All),
        "" => Err(Error::Config(format!(
            "source \"{name}\": no `selection` entry. This project selects a \
             source's cells geometrically (SPEC-LIT §18): box, sphere or all"
        ))),
        other => Err(Error::Config(format!(
            "source \"{name}\": selection \"{other}\" is not one this solver \
             understands. Available: box, sphere, all (SPEC-LIT §18, §13.4)"
        ))),
    }

fn write_constant(case_dir: &Path, nu: Scalar, model: &str, extra: &str) -> Result<()> {
    let dir = case_dir.join("constant");

    write_dict(
        &dir,
        "physicalProperties",
        &format!(
            "viscosityModel  constant;\n\nnu              [0 2 -1 0 0 0 0] {};{extra}",
            fmt_g(nu)
        ),
    )?;

    // No `blended` entry. ofgpu always blends the two branches of the law
    // of the wall, so there is nothing for a switch to select; see the note
    // beside `WallFunctionCoeffs` in `io::case` for why the switch was
    // removed rather than implemented.
    write_dict(
        &dir,
        "momentumTransport",
        &format!(
            "simulationType  RAS;\n\nRAS\n{{\n\
             \x20   model           {model};\n\
             \x20   turbulence      on;\n\
             \x20   printCoeffs     on;\n\
}}"
        ),
    )
